// Generated by `factory render`. Do not edit.
// Parsers for what analysis tools print or write. Each returns findings as
//   { rule, level: error | warning | note, file (as the tool printed it), line | null, message, snippet | null, key | null }
// `key` is a tool's own stable identity for a finding that has no line (a vulnerable package) or must not be stored
// (a secret: only a hash of it). A pack's own parser is a module (`parse: "module:<path>"`) exporting
// `parse(text, { root })` and, for `factory doctor`, `sample`.
import { rememberSecret } from '../redact.mjs';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
import { cweOf, normalizeVendorSeverity, sarifTriage } from './commercial.mjs';

const ANSI = new RegExp(`${String.fromCharCode(27)}\\[[0-9;]*m`, 'g');
const strip = (s) => String(s ?? '').replace(ANSI, '');
const level = (l) => (['error', 'warning', 'note'].includes(l) ? l : l === 'none' ? 'note' : l === 'info' || l === 'information' || l === 'hint' ? 'note' : 'warning');
const hash = (s) => createHash('sha256').update(String(s)).digest('hex').slice(0, 16);

function json(text) {
  const t = String(text ?? '').trim();
  if (!t) return null;
  try {
    return JSON.parse(t);
  } catch {
    // A tool that prints a banner before its JSON: the first { or [ to the end.
    const i = t.search(/[[{]/);
    if (i > 0) {
      try {
        return JSON.parse(t.slice(i));
      } catch {
        return undefined;
      }
    }
    return undefined;
  }
}

// SARIF 2.1.0: every run's results, with the rule's default level when a result has none.
export function parseSarif(text) {
  const doc = json(text);
  if (!doc || !Array.isArray(doc.runs)) throw new Error('not a SARIF log (no "runs")');
  const out = [];
  for (const run of doc.runs) {
    const rules = new Map();
    for (const r of [...(run.tool?.driver?.rules ?? []), ...(run.tool?.extensions ?? []).flatMap((e) => e.rules ?? [])]) rules.set(r.id, r);
    for (const r of run.results ?? []) {
      const ruleId = r.ruleId ?? r.rule?.id ?? (Number.isInteger(r.ruleIndex) ? run.tool?.driver?.rules?.[r.ruleIndex]?.id : null) ?? 'unknown';
      const rule = rules.get(ruleId);
      const loc = r.locations?.[0]?.physicalLocation;
      let uri = loc?.artifactLocation?.uri ?? null;
      if (uri) {
        uri = uri.startsWith('file://') ? decodeURIComponent(new URL(uri).pathname).replace(/^\/([A-Za-z]:)/, '$1') : decodeURIComponent(uri);
      }
      const fingerprint = r.partialFingerprints ? Object.values(r.partialFingerprints)[0] : r.fingerprints ? Object.values(r.fingerprints)[0] : null;
      out.push({
        rule: ruleId,
        level: level(r.level ?? rule?.defaultConfiguration?.level ?? 'warning'),
        file: uri,
        line: Number.isInteger(loc?.region?.startLine) ? loc.region.startLine : null,
        // The match's columns where the tool gives them (a secret scanner: the span its rule matched; secrets.mjs reads
        // the value there to tell a copy of a value already on the base from a new one).
        ...(Number.isInteger(loc?.region?.startColumn) ? { column: loc.region.startColumn } : {}),
        ...(Number.isInteger(loc?.region?.endColumn) && loc?.region?.endLine === loc?.region?.startLine ? { endColumn: loc.region.endColumn } : {}),
        message: strip(r.message?.text ?? r.message?.markdown ?? rule?.shortDescription?.text ?? ruleId),
        snippet: loc?.region?.snippet?.text ?? null,
        key: uri ? null : fingerprint ?? null,
        // What a commercial scanner says beyond the level (absent fields stay absent: open-source tools' reports are
        // unchanged): the vendor's severity (security-severity score or word), the weakness (CWE), the vendor's own
        // fingerprint, and a suppression or triage decision made in the vendor's system.
        ...vendorFields(r, rule, fingerprint),
      });
    }
  }
  return out;
}

function vendorFields(r, rule, fingerprint) {
  const props = { ...(rule?.properties ?? {}), ...(r.properties ?? {}) };
  const out = {};
  const sev = normalizeVendorSeverity(props['security-severity'] ?? props.severity ?? props.priority ?? null);
  if (sev) out.vendorSeverity = sev;
  const cwe = cweOf(props.cwe, props.tags, props.cwe_ids, rule?.relationships?.map((x) => x?.target?.id));
  if (cwe) out.cwe = cwe;
  if (fingerprint) out.vendorFingerprint = String(fingerprint);
  const triage = sarifTriage(r);
  if (triage) out.triage = triage;
  return out;
}

// MSBuild / the .NET compilers and analyzers: `path(12,5): error CA2100: message [project]`.
export function parseMsbuild(text) {
  const out = [];
  const seen = new Set();
  for (const raw of strip(text).split('\n')) {
    const m = /^\s*(.+?)\((\d+)(?:,\d+)*\)\s*:\s*(error|warning|info|message)\s+([A-Za-z]+\d+|[\w.-]+)\s*:\s*(.*?)(?:\s+\[[^\]]+\])?\s*$/.exec(raw);
    if (!m) continue;
    const f = { rule: m[4], level: level(m[3]), file: m[1].trim(), line: Number(m[2]), message: m[5], snippet: null, key: null };
    // MSBuild prints each diagnostic once per project that builds the file, and again in its summary.
    const id = `${f.file}|${f.line}|${f.rule}|${f.message}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push(f);
  }
  return out;
}

// ESLint's JSON formatter (`-f json`).
export function parseEslintJson(text) {
  const doc = json(text);
  if (!Array.isArray(doc)) throw new Error('not ESLint JSON output (an array of files)');
  return doc.flatMap((file) => (file.messages ?? []).map((m) => ({ rule: m.ruleId ?? (m.fatal ? 'parse-error' : 'unknown'), level: m.severity === 2 ? 'error' : 'warning', file: file.filePath, line: Number.isInteger(m.line) ? m.line : null, message: m.message, snippet: null, key: null })));
}

// ESLint's default (stylish) output: a file header, then `  12:5  error  message  rule-id` lines.
export function parseEslintStylish(text) {
  const out = [];
  let header = null;
  for (const raw of strip(text).split('\n')) {
    const line = raw.replace(/\r$/, '');
    if (/^\S.*\.[\w]+$/.test(line.trim()) && !/^\s/.test(line) && !/\s{2}/.test(line)) {
      header = line.trim();
      continue;
    }
    const m = /^\s+(\d+):\d+\s+(error|warning)\s+(.*?)(?:\s{2,}(\S+))?\s*$/.exec(line);
    if (m && header) out.push({ rule: m[4] ?? 'unknown', level: m[2], file: header, line: Number(m[1]), message: m[3], snippet: null, key: null });
  }
  return out;
}

// Anything that prints `path:12[:5]: [level] [rule] message` or `path(12,5) ...` (gcc-style tools, ruff, markdownlint,
// `dotnet format --verify-no-changes`), and ESLint's stylish output: the formats the changed-lines lint understands.
export function parseLines(text) {
  const out = [];
  let header = null;
  for (const raw of strip(text).split('\n')) {
    const line = raw.replace(/\r$/, '');
    let m = /^\s*([^\s:()]+\.[\w]+)\((\d+),\d+(?:,\d+,\d+)?\)\s*:?\s*(error|warning|info)?\s*([A-Za-z]+\d+|[\w./-]+)?\s*:?\s*(.*)$/.exec(line);
    if (m) {
      out.push({ rule: m[4] ?? 'lint', level: level(m[3] ?? 'error'), file: m[1], line: Number(m[2]), message: m[5]?.trim() || line.trim(), snippet: null, key: null });
      continue;
    }
    m = /^([^\s:]+\.[\w]+):(\d+)(?::\d+)?(?=[:\s]|$)[:\s]*(?:(error|warning|info|note)\b[:\s]*)?(?:\[?([A-Za-z]+[\w/-]*\d+|[a-z]+(?:-[a-z]+)+)\]?[:\s]+)?(.*)$/.exec(line);
    if (m) {
      out.push({ rule: m[4] ?? 'lint', level: level(m[3] ?? 'error'), file: m[1], line: Number(m[2]), message: m[5]?.trim() || line.trim(), snippet: null, key: null });
      continue;
    }
    if (/^\S.*\.[\w]+$/.test(line.trim()) && !/\s{2}/.test(line)) header = line.trim();
    m = /^\s+(\d+):\d+\s+(error|warning)\s+(.*?)(?:\s{2,}(\S+))?\s*$/.exec(line);
    if (m && header) out.push({ rule: m[4] ?? 'lint', level: m[2], file: header, line: Number(m[1]), message: m[3], snippet: null, key: null });
  }
  return out;
}

const rememberValue = (v, rule) => {
  rememberSecret(v, rule ?? 'secret');
  return false;
};

// gitleaks' JSON report. The secret itself is never kept: only a hash of it, so a finding is recognised again
// across rounds and against the merge-base without the value ever reaching a report, a log or an agent.
export function parseGitleaksJson(text) {
  const doc = json(text);
  if (doc === null) return [];
  if (!Array.isArray(doc)) throw new Error('not a gitleaks JSON report (an array of findings)');
  for (const f of doc) rememberValue(f.Secret ?? f.Match, f.RuleID);
  return doc.map((f) => ({
    rule: f.RuleID ?? 'secret',
    level: 'error',
    file: f.File ?? null,
    line: Number.isInteger(f.StartLine) ? f.StartLine : null,
    message: `${f.Description ?? 'possible secret'}${f.Commit ? ` (commit ${String(f.Commit).slice(0, 12)})` : ''}`,
    snippet: null,
    // `leak-<hash>`: not `secret:<hash>`, a credential word before a hex string (redact.mjs). The value is remembered as a
    // hash so the redaction boundary removes it wherever it turns up later in the run.
    key: `leak-${hash(`${f.RuleID}|${f.Secret ?? f.Match ?? ''}`)}`,
    redacted: true,
  }));
}

// actionlint's JSON output (`-format '{{json .}}'`): [{ message, filepath, line, column, kind, snippet }].
export function parseActionlintJson(text) {
  const doc = json(text);
  if (doc === null) return [];
  if (!Array.isArray(doc)) throw new Error('not actionlint JSON output (an array of errors)');
  return doc.map((e) => ({ rule: e.kind ?? 'actionlint', level: 'error', file: e.filepath ?? null, line: Number.isInteger(e.line) ? e.line : null, message: strip(e.message ?? ''), snippet: null, key: null }));
}

// OSV-Scanner's JSON output: one finding per vulnerability group and package, identified by the advisory id and the
// package (not its version), so the same advisory on the merge-base is the same finding.
export function parseOsvJson(text) {
  const doc = json(text);
  if (doc === null) return [];
  if (!doc || !Array.isArray(doc.results)) throw new Error('not OSV-Scanner JSON output (no "results")');
  const out = [];
  for (const r of doc.results) {
    for (const p of r.packages ?? []) {
      const pkg = p.package ?? {};
      const groups = p.groups?.length ? p.groups : (p.vulnerabilities ?? []).map((v) => ({ ids: [v.id] }));
      for (const g of groups) {
        const ids = [...(g.ids ?? [])].sort();
        const id = ids.find((x) => /^GHSA-/.test(x)) ?? ids[0] ?? 'vulnerability';
        const sev = Number(g.max_severity);
        out.push({ rule: id, level: Number.isFinite(sev) && sev > 0 && sev < 4 ? 'warning' : 'error', file: r.source?.path ?? null, line: null, message: `${pkg.ecosystem ?? ''} ${pkg.name ?? '?'} ${pkg.version ?? ''} is affected by ${ids.join(', ')}${Number.isFinite(sev) && sev > 0 ? ` (CVSS ${sev})` : ''}`.trim(), snippet: null, key: `${pkg.ecosystem ?? ''}:${pkg.name ?? ''}:${id}` });
      }
    }
  }
  return out;
}

const BUILTIN = { sarif: parseSarif, msbuild: parseMsbuild, 'eslint-json': parseEslintJson, eslint: parseEslintStylish, lines: parseLines, gcc: parseLines, 'gitleaks-json': parseGitleaksJson, 'actionlint-json': parseActionlintJson, 'osv-json': parseOsvJson };

// One sample per built-in parser, with how many findings it holds (factory doctor checks each configured parser).
export const SAMPLES = {
  sarif: { text: JSON.stringify({ version: '2.1.0', runs: [{ tool: { driver: { name: 'sample', rules: [{ id: 'S1', defaultConfiguration: { level: 'error' } }] } }, results: [{ ruleId: 'S1', message: { text: 'sample' }, locations: [{ physicalLocation: { artifactLocation: { uri: 'src/a.x' }, region: { startLine: 3 } } }] }] }] }), count: 1 },
  msbuild: { text: 'src/A.cs(3,5): warning CA1000: sample [src/A.proj]\nsrc/A.cs(3,5): warning CA1000: sample [src/A.proj]\n', count: 1 },
  'eslint-json': { text: JSON.stringify([{ filePath: '/r/src/a.ts', messages: [{ ruleId: 'no-unused-vars', severity: 2, message: 'sample', line: 3 }] }]), count: 1 },
  eslint: { text: '/r/src/a.ts\n  3:5  error  sample  no-unused-vars\n', count: 1 },
  lines: { text: 'src/a.py:3:1: E501 line too long\n', count: 1 },
  gcc: { text: 'src/a.c:3:1: warning: sample\n', count: 1 },
  'actionlint-json': { text: JSON.stringify([{ message: 'sample', filepath: '.github/workflows/a.yml', line: 3, column: 1, kind: 'expression' }]), count: 1 },
  'osv-json': { text: JSON.stringify({ results: [{ source: { path: 'package-lock.json', type: 'lockfile' }, packages: [{ package: { name: 'left-pad', version: '1.0.0', ecosystem: 'npm' }, vulnerabilities: [{ id: 'GHSA-xxxx-yyyy-zzzz' }], groups: [{ ids: ['GHSA-xxxx-yyyy-zzzz'], max_severity: '7.5' }] }] }] }), count: 1 },
  'gitleaks-json': { text: JSON.stringify([{ RuleID: 'generic-api-key', Description: 'sample', File: 'a.env', StartLine: 1, Secret: 'not-a-real-secret', Commit: 'abc' }]), count: 1 },
};

const modules = new Map();
async function loadModule(file) {
  if (!modules.has(file)) modules.set(file, await import(pathToFileURL(file).href));
  return modules.get(file);
}

// The parser a tool names. Throws for an unknown one (validation catches that first).
export async function parserFor(name) {
  if (BUILTIN[name]) return { parse: BUILTIN[name], sample: SAMPLES[name] };
  if (String(name).startsWith('module:')) {
    const mod = await loadModule(name.slice(7));
    if (typeof mod.parse !== 'function') throw new Error(`${name.slice(7)} does not export parse(text, { root })`);
    return { parse: mod.parse, sample: mod.sample ?? null };
  }
  throw new Error(`unknown parser "${name}"`);
}

// Whether a parser understands its sample: [ok, detail].
export async function parserSelfTest(name) {
  try {
    const { parse, sample } = await parserFor(name);
    if (!sample) return [true, `${name}: no sample to check`];
    const got = parse(sample.text, { root: '/r' });
    return [got.length === sample.count, `${name}: ${got.length} finding(s) from its sample (expected ${sample.count})`];
  } catch (error) {
    return [false, `${name}: ${error.message}`];
  }
}
